import { defineConfig } from '@prisma/config';

/**
 * Host Beta's Prisma configuration. `prisma/schema/` is GENERATED by `platform db compose` from
 * the platform fragments, the `vault-db sync` copies and the host's own
 * `prisma/fragments/host.beta.prisma`. DATABASE_URL is set by the caller (the test harness, CI).
 */
export default defineConfig({
  schema: 'prisma/schema',
  datasource: { url: process.env.DATABASE_URL ?? 'postgresql://unused@localhost:5432/unused' },
  migrations: { path: 'prisma/migrations' },
});
